using System;

namespace StdbModule;

public static partial class EnglishQuotes
{
    public static class CarlSagan
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "We make our world significant by the courage of our questions and by the depth of our answers.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "The fact that some geniuses were laughed at does not imply that all who are laughed at are geniuses. They laughed at Columbus, they laughed at Fulton, they laughed at the Wright brothers. But they also laughed at Bozo the Clown.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "We live in a society absolutely dependent on science and technology and yet have cleverly arranged things so that almost no one understands science and technology. That's a clear prescription for disaster.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "Science is ... a way of skeptically interrogating the universe with a fine understanding of human fallibility. If we are not able to ask skeptical questions, to interrogate those who tell us that something is true, to be skeptical of those in authority, then we’re up for grabs for the next charlatan, political or religious, who comes ambling along.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "Imagine, a room, awash in gasoline. And there are two implacable enemies in that room. One of them has 9,000 matches. The other has 7,000 matches. Each of them is concerned about who's ahead, who's stronger. Well, that's the kind of situation we are actually in. The amount of weapons that are available to the United States and the Soviet Union are so bloated, so grossly in excess of what's needed to dissuade the other that if it weren't so tragic, it would be laughable.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "It seems to me what is called for is an exquisite balance between two conflicting needs: the most skeptical scrutiny of all hypotheses that are served up to us and at the same time a great openness to new ideas... If you are only skeptical, then no new ideas make it through to you... On the other hand, if you are open to the point of gullibility and have not an ounce of skeptical sense in you, then you cannot distinguish the useful ideas from the worthless ones.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "In science it often happens that scientists say, 'You know that's a really good argument; my position is mistaken,' and then they would actually change their minds and you never hear that old view from them again. They really do it. It doesn't happen as often as it should, because scientists are human and change is sometimes painful. But it happens every day. I cannot recall the last time something like that happened in politics or religion.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "We live in a society exquisitely dependent on science and technology, in which hardly anyone knows anything about science and technology.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "Not explaining science seems to me perverse. When you're in love, you want to tell the world.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "We've arranged a society based on science and technology, in which nobody understands anything about science and technology. And this combustible mixture of ignorance and power, sooner or later, is going to blow up in our faces. Who is running the science and technology in a democracy if the people don't know anything about it?", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "I know that science and technology are not just cornucopias pouring good deeds out into the world. Scientists not only conceived nuclear weapons; they also took political leaders by the lapels, arguing that 'their' nation — whichever it happened to be — had to have one first. ... There's a reason people are nervous about science and technology. The sword of science is double-edged.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "Science is much more than a body of knowledge. It is a way of thinking. This is central to its success. Science invites us to let the facts in, even when they don't conform to our preconceptions. It counsels us to carry alternative hypotheses in our heads and see which ones best match the facts. It urges on us a fine balance between no-holds-barred openness to new ideas, however heretical, and the most rigorous skeptical scrutiny of everything — new ideas and established wisdom. We need wide appreciation of this kind of thinking. It works. It's an essential tool for a democracy in an age of change. Our task is not just to train more scientists but also to deepen public understanding of science.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "Science is [...] a way of skeptically interrogating the universe with a fine understanding of human fallibility. If we are not able to ask skeptical questions, to interrogate those who tell us that something is true, to be skeptical of those in authority, then we're up for grabs for the next charlatan, political or religious, who comes ambling along.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "The idea that God is an oversized white male with a flowing beard who sits in the sky and tallies the fall of every sparrow is ludicrous. But if by God one means the set of physical laws that govern the universe, then clearly there is such a God. This God is emotionally unsatisfying... it does not make much sense to pray to the law of gravity.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "Humans — who enslave, castrate, experiment on, and fillet other animals — have had an understandable penchant for pretending animals do not feel pain. A sharp distinction between humans and 'animals' is essential if we are to bend them to our will, make them work for us, wear them, eat them — without any disquieting tinges of guilt or regret. It is unseemly of us, who often behave so unfeelingly toward other animals, to contend that only humans can suffer. The behavior of other animals renders such pretensions specious. They are just too much like us.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "The truth may be puzzling. It may take some work to grapple with. It may be counterintuitive. It may contradict deeply held prejudices. It may not be consonant with what we desperately want to be true. But our preferences do not determine what's true.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "Cleverly designed experiments are the key.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "Every kid starts out as a natural-born scientist, and then we beat it out of them. A few trickle through the system with their wonder and enthusiasm for science intact.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "I would love to believe that when I die I will live again, that some thinking, feeling, remembering part of me will continue. But much as I want to believe that, and despite the ancient and worldwide cultural traditions that assert an afterlife, I know of nothing to suggest that it is more than wishful thinking. The world is so exquisite with so much love and moral depth, that there is no reason to deceive ourselves with pretty stories for which there's little good evidence. Far better it seems to me, in our vulnerability, is to look death in the eye and to be grateful every day for the brief but magnificent opportunity that life provides.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "If you wish to make an apple pie from scratch, you must first invent the universe.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "That kind of skeptical, questioning, \"don't accept what authority tells you\" attitude of science — is also nearly identical to the attitude of mind necessary for a functioning democracy. Science and democracy have very consonant values and approaches, and I don't think you can have one without the other.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "Who is more humble? The scientist who looks at the universe with an open mind and accepts whatever it has to teach us, or somebody who says everything in this book must be considered the literal truth and never mind the fallibility of all the human beings involved?", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "Those who raise questions about the God hypothesis and the soul hypothesis are by no means all atheists. An atheist is someone who is certain that God does not exist, someone who has compelling evidence against the existence of God. I know of no such compelling evidence. Because God can be relegated to remote times and places and to ultimate causes, we would have to know a great deal more about the universe than we do to be sure that no such God exists. To be certain of the existence of God and to be certain of the nonexistence of God seem to me to be the confident extremes in a subject so riddled with doubt and uncertainty as to inspire very little confidence indeed.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "Not all bits have equal value.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "I think people in power have a vested interest to oppose critical thinking.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "To me, the principal trouble with this idea is that 99.998% of the lifetime of the universe, from its beginning to now, was over before humans appeared on the scene.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "There is a myth about such highs: the user has an illusion of great insight, but it does not survive scrutiny in the morning. I am convinced that this is an error, and that the devastating insights achieved when high are real insights; the main problem is putting these insights in a form acceptable to the quite different self that we are when we're down the next day.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "There's a part of me making, creating the perceptions which in everyday life would be bizarre; there's another part of me which is a kind of observer. About half of the pleasure comes from the observer-part appreciating the work of the creator-part. I smile, or sometimes even laugh out loud at the pictures on the insides of my eyelids.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "The cannabis experience has greatly improved my appreciation for art, a subject which I had never much appreciated before. The understanding of the intent of the artist which I can achieve when high sometimes carries over to when I'm down. This is one of many human frontiers which cannabis has helped me traverse.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "Cannabis also enhances the enjoyment of sex — on the one hand it gives an exquisite sensitivity, but on the other hand it postpones orgasm: in part by distracting me with the profusion of image passing before my eyes.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "I do not consider myself a religious person in the usual sense, but there is a religious aspect to some highs. The heightened sensitivity in all areas gives me a feeling of communion with my surroundings, both animate and inanimate.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "A sense of what the world is really like can be maddening; cannabis has brought me some feelings for what it is like to be crazy, and how we use that word 'crazy' to avoid thinking about things that are too painful for us.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "Many but not all my cannabis trips have somewhere in them a symbolism significant to me which I won't attempt to describe here, a kind of mandala embossed on the high. Free-associating to this mandala, both visually and as plays on words, has produced a very rich array of insights.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "I find that most of the insights I achieve when high are into social issues, an area of creative scholarship very different from the one I am generally known for.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "I say 'Listen closely, you sonofabitch of the morning! This stuff is real!'", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "I am convinced that there are genuine and valid levels of perception available with cannabis (and probably with other drugs) which are, through the defects of our society and our educational system, unavailable to us without such drugs.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "My high is always reflective, peaceable, intellectually exciting, and sociable, unlike most alcohol highs, and there is never a hangover.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "R is very large for LSD (which I've never taken) and reasonably short for cannabis. Small values of R should be one measure of the safety of psychedelic drugs.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "The illegality of cannabis is outrageous, an impediment to full utilization of a drug which helps produce the serenity and insight, sensitivity and fellowship so desperately needed in this increasingly mad and dangerous world.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "I proffer the following ideas with a substantial degree of trepidation; I know very well that many of them are speculative and can be proved or disproved on the anvil of experiment.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "My fundamental premise about the brain is that its workings—what we sometimes call 'mind'—are a consequence of its anatomy and physiology, and nothing more.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "Absence of evidence is not evidence of absence.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "The entire recent history of biology shows that we are, to a remarkable degree, the results of the interactions of an extremely complex array of molecules; and the aspect of biology that was once considered its holy of holies, the nature of the genetic material, has now been fundamentally understood in terms of the chemistry of its constituent nucleic acids, DNA and RNA, and their operational agents, the proteins.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "Those at too great a distance may, I am well aware, mistake ignorance for perspective.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "It is important to distinguish between the amount of information and the quality of that information.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "Note that in all this interaction between mutation and natural selection, no moth is making a conscious 'effort' to adapt to a changed environment. The process is random and statistical.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "There is a popular contention that half or more of the brain is unused. From an evolutionary point of view this would be quite extraordinary: why should it have evolved if it had no function? But actually the statement is made on very little evidence.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "The price we pay for the anticipation of our future is anxiety about it. Foretelling disaster is probably not much fun; Pollyanna was much happier than Cassandra. But the Cassandric components of our nature are necessary for survival.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "While ritual, emotion and reasoning are all significant aspects of human nature, the most nearly unique human characteristic is the ability to associate abstractly and to reason. Curiosity and the urge to solve problems are the emotional hallmarks of our species; and the most characteristically human activities are mathematics, science, technology, music and the arts--a somewhat broader range of subjects than is usually included under the 'humanities.' Indeed, in its common usage this very word seems to reflect a peculiar narrowness of vision about what is human. Mathematics is as much a 'humanity' as poetry.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "Evolution often uses this strategy. Indeed, the standard evolutionary practice of increasing the amount of genetic information as organisms increase in complexity is accomplished by doubling part of the genetic material and then allowing the slow specialization of function of the redundant set.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "There is no doubt that right-hemisphere intuitive thinking may perceive patterns and connections too difficult for the left hemisphere; but it may also detect patterns where none exist. Skeptical and critical thinking is not a hallmark of the right hemisphere. And unalloyed right-hemisphere doctrines, particularly when they are invented during new and trying circumstances, may be erroneous or paranoid.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "There is no way to tell whether the patterns extracted by the right hemisphere are real or imagined without subjecting them to left-hemisphere scrutiny. On the other hand, mere critical thinking, without creative and intuitive insights, without the search for new patterns, is sterile and doomed. To solve complex problems in changing circumstances requires the activity of both cerebral hemispheres: the path to the future lies through the corpus callosum.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "The search for patterns without critical analysis, and rigid skepticism without a search for patterns, are the antipodes of incomplete science. The effective pursuit of knowledge requires both functions.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "Without these experimental tests, very few physicists would have accepted general relativity. There are many hypotheses in physics of almost comparable brilliance and elegance that have been rejected because they did not survive such a confrontation with experiment. In my view, the human condition would be greatly improved if such confrontations and willingness to reject hypotheses were a regular part of our social, political, economic, religious and cultural lives.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "Anatomy is not destiny, but it is not irrelevant either.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "In general, human societies are not innovative. They are hierarchical and ritualistic. Suggestions for change are greeted with suspicion: they imply an unpleasant future variation in ritual and hierarchy: an exchange of one set of rituals for another, or perhaps for a less structured society with fewer rituals. And yet there are times when societies must change. \"The dogmas of the quiet past are inadequate for the stormy present\" was Abraham Lincoln’s description of this truth.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "The integrity of the experimenters in the face of this unexpected finding is breathtaking. (It is difficult to imagine any experiment that would convince leading practitioners of many political or religious philosophies of the superiority of a competing doctrine.)", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "To me it is not in the least demeaning that consciousness and intelligence are the result of 'mere' matter sufficiently complexly arranged; on the contrary, it is an exalting tribute to the subtlety of matter and the laws of Nature.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "That in nonarithmetic operations the small and slow human brain can still do so much better than the large and fast electronic computer is an impressive tribute to how cleverly the brain is packaged and programmed—features brought about, of course, by natural selection.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "The entire evolutionary record on our planet, particularly the record contained in fossil endocasts, illustrates a progressive tendency toward intelligence. There is nothing mysterious about this: smart organisms by and large survive better and leave more offspring than stupid ones.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "Once intelligent beings achieve technology and the capacity for self-destruction of their species, the selective advantage of intelligence becomes more uncertain.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "Natural selection has served as a kind of intellectual sieve, producing brains and intelligences increasingly competent to deal with the laws of nature. This resonance, extracted by natural selection, between our brains and the universe may help explain a quandary set by Einstein: The most incomprehensible property of the universe, he said, is that it is so comprehensible.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "Both borderline science and many religions are motivated in part by a serious concern about the nature of the universe and our role in it, and for this reason merit our consideration and regard.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "The well-meaning contention that all ideas have equal merit seems to me little different from the disastrous contention that no ideas have any merit.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "Broca was quoted as saying, “I would rather be a transformed ape than a degenerate son of Adam.”", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "Society corrupts the best of us. It is a little unfair, I think, to criticize a person for not sharing the enlightenment of a later epoch, but it is also profoundly saddening that such prejudices were so extremely pervasive.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "All inquiries carry with them some element of risk. There is no guarantee that the universe will conform to our predispositions. But I do not see how we can deal with the universe—both the outside and the inside universe—without studying it.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "Our perceptions may be distorted by training and prejudice or merely because of the limitations of our sense organs, which, of course, perceive directly but a small fraction of the phenomena of the world.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "Whether in some sense the universe is ultimately knowable depends not only on how many natural laws there are that encompass widely divergent phenomena, but also on whether we have the openness and the intellectual capacity to understand such laws.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "For myself, I like a universe that includes much that is unknown and, at the same time, much that is knowable. A universe in which everything is known would be static and dull, as boring as the heaven of some weak-minded theologians.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "People are rarely grateful for a demonstration of their credulity.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "For many people, the shoddily thought out doctrines of borderline science are the closest approximation to comprehensible science readily available. The popularity of borderline science is a rebuke to the schools, the press and commercial television for their sparse, unimaginative and ineffective efforts at science education; and to us scientists, for doing so little to popularize our subject.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "But our openness to the dazzling possibilities presented by modern science must be tempered by some hard-nosed skepticism. Many interesting possibilities simply turn out to be wrong. An openness to new possibilities and a willingness to ask hard questions are both required to advance our knowledge.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "Very few scientists actually plunge into the murky waters of testing or challenging borderline or pseudo-scientific beliefs. The chance of finding out something really interesting—except about human nature—seems small, and the amount of time required seems large.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "I believe that the extraordinary should certainly be pursued. But extraordinary claims require extraordinary evidence.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "Where skeptical observation and discussion are suppressed, the truth is hidden.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "The best antidote for pseudoscience, I firmly believe, is science.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "I believe that even a smattering of such findings in modern science and mathematics is far more compelling and exciting than most of the doctrines of pseudoscience, whose practitioners were condemned as early as the fifth century B.C. by the Ionian philosopher Heraclitus as 'nightwalkers, magicians, priests of Bacchus, priestesses of the wine-vat, mystery-mongers.'", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "Scientists, like other human beings, have their hopes and fears, their passions and despondencies—and their strong emotions may sometimes interrupt the course of clear thinking and sound practice. But science is also self-correcting. The most fundamental axioms and conclusions may be challenged.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "The idea of science as a method rather than as a body of knowledge is not widely appreciated outside of science, or indeed in some corridors inside of science.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "Vigorous criticism is more constructive in science than in some other areas of human endeavor because in science there are adequate standards of validity that can be agreed upon by competent practitioners the world over.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "It is merely a coincidence. When enough fiction is written and enough scientific hypotheses are proposed, sooner or later there will be accidental concordances.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "St. Anselm argued that since we can imagine a perfect being, he must exist—because he would not be perfect without the added perfection of existence.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "In the face of all this, many of the standard ideas of science fiction seem to me to pale by comparison. I see the relative absence of these things and the distortions of scientific thinking often encountered in science fiction as terrible wasted opportunities.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "Many scientists deeply involved in the exploration of the solar system (myself among them) were first turned in that direction by science fiction. And the fact that some of that science fiction was not of the highest quality is irrelevant.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "Every new set of discoveries raises a host of questions which we were never before wise enough even to ask.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "Much of human history can, I think, be described as a gradual and sometimes painful liberation from provincialism, the emerging awareness that there is more to the world than was generally believed by our ancestors.", Author = "Carl Sagan" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Carl_Sagan", Text = "The search for extraterrestrial intelligence is the search for a generally acceptable cosmic context for the human species. In the deepest sense, the search for extraterrestrial intelligence is a search for ourselves.", Author = "Carl Sagan" },
        };
    }
}